9:  * @see http://stackoverflow.com/questions/2603912/php-set-timeout-for-script-with-system-call-set-time-limit-not-working
10:  *
11:  * @param string $cmd Command to exec (you should use 2>&1 at the end to pipe all output)
12:  * @param integer $timeout
13:  * @return string Returns command output
14:  *
15:  *
16:  * Edvard Rejthar, IntelMQ developer: it was the only function that was able to correctly timeout an eternal command;
17:  * many others let my nginx stuck forever. Ubuntu 17.10, let's hope it'll work for youtoo.
18:  */
19: function ExecWaitTimeout($cmd, $timeout = 5) {
20: 
21:     $descriptorspec = array(
22:         0 => array("pipe", "r"),
23:         1 => array("pipe", "w"),
24:         2 => array("pipe", "w")
25:     );
26:     $pipes = array();
27: 
28:     $timeout += time();
29:     $process = proc_open($cmd, $descriptorspec, $pipes);
30:     if (!is_resource($process)) {
31:         throw new Exception("proc_open failed on: " . $cmd);
32:     }
33: 
34:     $output = '';
35: 
36: 
37:     do {
38:         $timeleft = $timeout - time();
39:         $read = array($pipes[1]);
40:         $write = NULL;
41:         $exeptions = NULL;
42:         stream_select($read, $write, $exeptions, $timeleft, NULL);
43: 
44:         if (!empty($read)) {
45:             $output .= fread($pipes[1], 8192);
46:         }
47:     } while (!feof($pipes[1]) && $timeleft > 0);
48: 
49:     if ($timeleft <= 0) {
50:         proc_terminate($process);
51:         return $output;
52:         //throw new Exception("command timeout on: " . $cmd . " $output");
53:     } else {
54:         return $output;
55:     }
56: }
